INSERT INTO `databab_bukhari` (`id_kitab`, `id_bab`, `bab_indonesia`, `bab_arab`) VALUES
(1,	1,	'Permulaan wahyu',	' بدء الوحي'),
(2,	2,	'Islam dibangun diatas lima (landasan), dan Islam adalah perkataan dan perbuatan serta bertambah dan berkurang.',	' بني الإسلام على خمس'),
(2,	3,	'Tentang Perkara-perkara Iman',	' أمور الإيمان'),
(2,	4,	'Seorang muslim adalah orang yang Kaum Muslimin selamat dari lisan dan tangannya',	' المسلم من سلم المسلمون من لسانه ويده'),
(2,	5,	'Amalan Islam apakah yang paling utama?',	' أي الإسلام أفضل'),
(2,	6,	'Memberi makan bagian dari Islam',	' إطعام الطعام من الإسلام'),
(2,	7,	'Bagian dari iman hendaknya mencintai untuk saudaranya sebagaimana dia mencintai untuk dirinya sendiri',	' من الإيمان أن يحب لأخيه ما يحب لنفسه'),
(2,	8,	'Mencintai Rasulullah bagian dari iman',	' حب الرسول صلى الله عليه وسلم من الإيمان'),
(2,	9,	'Manisnya iman',	' حلاوة الإيمان'),
(2,	10,	'Tanda-tanda keimanan adalah mencintai sahabat anshar',	' علامة الإيمان حب الأنصار'),
(2,	11,	'Bagian dari dien adalah menghindar dari fitnah',	' من الدين الفرار من الفتن'),
(2,	12,	'Sabda nabi shallallahu \'alai wa sallam; \'Di antara kalian akulah yang paling mengerti tentang Allah\'',	' قول النبي صلى الله عليه وسلم أنا أعلمكم بالله'),
(2,	13,	'Dan siapa yang benci kembali kepada kekufuran seperti dia benci bila dilempar ke neraka',	' من كره أن يعود في الكفر كما يكره أن يلقى في النار من'),
(2,	14,	'Bertingkat-tingkatnya ahlul imam dalam amalan',	' تفاضل أهل الإيمان في الأعمال'),
(2,	15,	'Malu bagian dari iman ',	' الحياء من الإيمان'),
(2,	16,	'\"Maka jika mereka bertaubat, menegakkan shalat dan membayar zakat, maka berilah kebebasan kepada mereka untuk berjalan.\"',	' فإن تابوا وأقاموا الصلاة وآتوا الزكاة فخلوا سبيلهم'),
(2,	17,	'Orang yang berpendapat bahwa iman adalah perbuatan.',	' من قال إن الإيمان هو العمل'),
(2,	18,	'Apabila masuk Islam bukan pada hakikatnya, tetapi karena berserahdiri dan takut dari pembunuhan',	' إذا لم يكن الإسلام على الحقيقة وكان على الاستسلام أو'),
(2,	19,	'Menyebarkan salam bagian dari Islam',	' إفشاء السلام من الإسلام'),
(2,	20,	'Mengingkari pemberian dan istilah kekufuran di bawah kekufuran',	' كفران العشير وكفر دون كفر'),
(2,	21,	'Perbuatan maksiat merupakan kebiasaan jahiliyah, namun pelakunya tidak dikafirkan karena kemaksiatannya ',	' المعاصي من أمر الجاهلية ولا يكفر صاحبها بارتكابها'),
(2,	22,	'Bila dua kelompoik orang beriman berperang maka damaikanlah…',	' وإن طائفتان من المؤمنين اقتتلوا فأصلحوا بينهما فسماهم'),
(2,	23,	'Kezhaliman di bawah kezhaliman',	' ظلم دون ظلم'),
(2,	24,	'Tanda-tanda nifaq',	' علامة المنافق'),
(2,	25,	'Menghidupkan malam lailatul qadar bagiand iman',	' قيام ليلة القدر من الإيمان'),
(2,	26,	'Jihad bagian dari iman',	' الجهاد من الإيمان'),
(2,	27,	'Menghidupkan ibadah-ibadah sunnah Ramadan bagian iman',	' تطوع قيام رمضان من الإيمان'),
(2,	28,	'Melaksanakan shaum Ramadan karena mencari ridla Allah bagian dari iman ',	' صوم رمضان احتسابا من الإيمان'),
(2,	29,	'Agama itu mudah',	' الدين يسر'),
(2,	30,	'Shalat bagian dari iman',	' الصلاة من الإيمان'),
(2,	31,	'Baiknya Islam seseorang',	' حسن إسلام المرء'),
(2,	32,	'Pelaksaan agama yang paling Allah sukai adalah yang konsisten',	' أحب الدين إلى الله عز وجل أدومه'),
(2,	33,	'Bertambah dan berkurangnya iman',	' زيادة الإيمان ونقصانه'),
(2,	34,	'Zakat bagian dari Islam',	' الزكاة من الإسلام'),
(2,	35,	'Mengiringi jenazah bagian dari iman',	' اتباع الجنائز من الإيمان'),
(2,	36,	'Kekhawatiran seorang mu\'min bila amalnya terhapus tanpa sadar  ',	' خوف المؤمن من أن يحبط عمله وهو لا يشعر'),
(2,	37,	'Pertanyaan malaikat Jibril kepada Nabi Shallallahu \'alaihi wa salam tentang iman, Islam, Ihsan dan pengetahuan akan hari qiyamat.',	' سؤال جبريل النبي صلى الله عليه وسلم عن الإيمان والإسلام'),
(2,	38,	'Keutamaan orang yang memelihara agamanya',	' فضل من استبرأ لدينه'),
(2,	39,	'Menunaikan pembagian seperlima bagian ghanimah merupakan bagian dari iman',	' أداء الخمس من الإيمان'),
(2,	40,	'Sesungguhnya amal itu bergantung dengan niat dan pengharapan, dan setiap mukmin akan mendapatkan sesuai dengan niatnya ',	' ما جاء إن الأعمال بالنية والحسبة ولكل امرئ ما نوى'),
(2,	41,	'Agama adalah nasehat (loyalitas) kepada Allah,Rasul-Nya dan para pemimpin.',	' الدين النصيحة لله ولرسوله ولأئمة المسلمين وعامتهم'),
(3,	43,	'Siapa yang bertanya tentag ilmu sedang dia terus menyampaikan pertanyaannnya….',	' من سئل علما وهو مشتغل في حديثه فأتم الحديث ثم أجاب'),
(3,	44,	'Siapa yang mengeraskan suaranya dalam menyampaikan ilmu',	' من رفع صوته بالعلم'),
(3,	45,	'Ucapan ahli hadits, telah bercerita kepada kami, telah mengabarkan kepada kami …',	' قول المحدث حدثنا وأخبرنا وأنبأنا'),
(3,	46,	'Pemimpin menyampaikan pertanyaan kepada kepada para sahabatnya untuk mengatahui kadar ilmu mereka ',	' طرح الإمام المسألة على أصحابه ليختبر ما عندهم من'),
(3,	47,	'Keterangan tentang ilmu,diantaranya firman Allah Ta\'ala: \"Dan katakanlah, Ya Rabb tambahkanlah aku ilmu…\"',	' ما جاء في العلم وقوله تعالى وقل رب زدني علما القراءة'),
(3,	48,	'Metode munawalah dan surat-surat para ahli ilmu ke berbagai negeri.',	' ما يذكر في المناولة وكتاب أهل العلم بالعلم إلى البلدان'),
(3,	49,	'Siapa yang duduk di belakang dalam suatu majelis',	' من قعد حيث ينتهي به المجلس ومن رأى فرجة في الحلقة'),
(3,	50,	'Sabda Nabi Shallallahu \'alaihi wa salam: \"Berapa banyak orang yang hanya mendapat penyampaian lebih paham dibanding orang yang  mendengarnya langsung ',	' قول النبي صلى الله عليه وسلم رب مبلغ أوعى من'),
(3,	52,	'Nabi Shallallahu \'alaihi wa salam selalu memberi waktu yang tepat ketika memberi nasehat',	' ما كان النبي صلى الله عليه وسلم يتخولهم بالموعظة'),
(3,	53,	'Orang yang menyediakan hari-hari khusus untuk bermulazamah dengan para ulama',	' من جعل لأهل العلم أياما معلومة'),
(3,	54,	'Siapa yang dikehendaki baik oleh Allah, maka Allah pahamkan dia tentang agama',	' من يرد الله به خيرا يفقهه في الدين'),
(3,	55,	'Memahami ilmu',	' الفهم في العلم'),
(3,	56,	'Tekun dalam mencari ilmu dan hikmah',	' الاغتباط في العلم والحكمة'),
(3,	57,	'Perginya Nabi Musa Alaihissalam kelaut untuk menemui Khidlir ',	' ما ذكر في ذهاب موسى صلى الله عليه وسلم في البحر إلى'),
(3,	58,	'Sabda Nabi Shallallahu \'alaihi wa salam: \"Ya Allah ajarkanlah dia al-Kitab\".',	' قول النبي صلى الله عليه وسلم اللهم علمه الكتاب'),
(3,	59,	'Kapan dibolehkan mendengarkan pendapat anak kecil',	' متى يصح سماع الصغير'),
(3,	60,	'Pergi menuntut ilmu',	' الخروج في طلب العلم'),
(3,	61,	'Keutamaan orang yang berilmu dan mengajarkannya',	' فضل من علم وعلم'),
(3,	62,	'Diangkatnya ilmu dan munculnya kebodohan',	' رفع العلم وظهور الجهل'),
(3,	63,	'Keutamaan ilmu',	' فضل العلم'),
(3,	64,	'Menberikan fatwa ketika sedang menunggang kendaraan..',	' الفتيا وهو واقف على الدابة وغيرها'),
(3,	65,	'Menjawab fatwa dengan isyarat tangan atau anggukan kepala',	' من أجاب الفتيا بإشارة اليد والرأس'),
(3,	66,	'Anjuran Nabi Shallallahu \'alaihi wa salam kepada utusan \'Abdul Qais untuk menjaga iman',	' تحريض النبي صلى الله عليه وسلم وفد عبد القيس على'),
(3,	67,	'Bepergian untuk mencari jawaban tentang masalah yang terjadi',	' الرحلة في المسألة النازلة وتعليم أهله'),
(3,	68,	'Bergantian dalam mencari ilmu',	' التناوب في العلم'),
(3,	69,	'Marah ketika memberi nasehat dan mengajar jika nelihat sesuatu yang dibenci',	' الغضب في الموعظة والتعليم إذا رأى ما يكره'),
(3,	70,	'Mencari berkah dengan bersimpuh kepada imam atau ahli hadits ',	' من برك على ركبتيه عند الإمام أو المحدث'),
(3,	71,	'Mengulang hadits sampai tiga kali agar dapat difahami',	' من أعاد الحديث ثلاثا ليفهم عنه'),
(3,	72,	'Mengajarkan ilmu kepada hamba sahaya dan keluarganya',	' تعليم الرجل أمته وأهله'),
(3,	73,	'Pemimpin memberikan nasehat dan pengajaran kepada kaum wanita ',	' عظة الإمام النساء وتعليمهن'),
(3,	74,	'Antusias untuk mencari hadits',	' الحرص على الحديث'),
(3,	75,	'Cara dicabutnya ilmu',	' كيف يقبض العلم'),
(3,	76,	'Perlukan menetapkan hari tertentu untuk megajarkan ilmu kepada kaum wanita?.',	' هل يجعل للنساء يوم على حدة في العلم'),
(3,	77,	'Siapa yang mendengar sesuatu namun belum dipahaminya hendaklah dia kembali (mendengarkannya) sampai mengerti',	' من سمع شيئا فلم يفهمه فراجع فيه حتى يعرفه'),
(3,	78,	'Orang yang hadir hendaklah menyampaikan ilmu yang didengarnya kepada yang tidak hadir',	' ليبلغ العلم الشاهد الغائب'),
(3,	79,	'Dosa orang yang berdusta atas nama Nabi Shallallahu \'alaihi wa salam ',	' إثم من كذب على النبي صلى الله عليه وسلم'),
(3,	80,	'Penulisan ilmu',	' كتابة العلم'),
(3,	81,	'Menyampaikan ilmu dan pelajaran di malam hari',	' العلم والعظة بالليل'),
(3,	82,	'Membicarakan ilmu sebelum tidur',	' السمر في العلم'),
(3,	83,	'Menghafal ilmu',	' حفظ العلم'),
(3,	84,	'Diam untuk mendengarkan ulama',	' الإنصات للعلماء'),
(3,	85,	'Anjuran untuk seorang alim, bila ditanya tentang siapakah yang lebih mengetahui, hendaklah  mengembalikan ilmu kepada Allah',	' ما يستحب للعالم إذا سئل أي الناس أعلم فيكل العلم'),
(3,	86,	'Bertanya sambil berdiri kepada seorang alim yang sedang duduk',	' من سأل وهو قائم عالما جالسا'),
(3,	87,	'Bertanya dan memberi fatwa ketika sedang melempar jumrah',	' السؤال والفتيا عند رمي الجمار'),
(3,	88,	'Firman Allah Ta\'ala : \"Dan tidaklah kalian diberi ilmu kecuali sedidkit…\"',	' قول الله تعالى وما أوتيتم من العلم إلا قليلا'),
(3,	89,	'Meninggalkan sebagian ikhtiar karena khawatir sebagian manusia tidak memahaminya sehingga melakukan kesalahan yang lebih besar',	' من ترك بعض الاختيار مخافة أن يقصر فهم بعض الناس عنه'),
(3,	90,	'Mengkhususkan sebagian iilmu kepada sebagian orang karena khawatir yag lainnya tidak dapat memahami',	' من خص بالعلم قوما دون قوم كراهية أن لا يفهموا'),
(3,	91,	'Malu dalam (menuntut) ilmu',	' الحياء في العلم'),
(3,	92,	'Orang yang malu bertanya lalu menyuruh orang lain untuk bertanya',	' من استحيا فأمر غيره بالسؤال'),
(3,	93,	'Menyampaikan ilmu dan fatwa di dalam masjid',	' ذكر العلم والفتيا في المسجد'),
(3,	94,	'Menjawab pertanyaan melebihi yang ditanyakan',	' من أجاب السائل بأكثر مما سأله'),
(4,	96,	'Shalat tidak diterima tanpa wudlu\'',	' لا تقبل صلاة بغير طهور'),
(4,	97,	'Keutamaan wudlu\' dan cahaya di wajah karena wudlu\'',	' فضل الوضوء والغر المحجلون من آثار الوضوء'),
(4,	98,	'Keraguan apakah masih punya wudlu\'',	' من لا يتوضأ من الشك حتى يستيقن'),
(4,	99,	'Ringan (hemat) dalam berwewudlu\'',	' التخفيف في الوضوء'),
(4,	100,	'Menyempurnakan wudlu\'',	' إسباغ الوضوء'),
(4,	101,	'Membasuh muka dengan kedua belah tangan dari satu cidukan',	' غسل الوجه باليدين من غرفة واحدة'),
(4,	102,	'Membaca basmalah dalam segala kegiatan termasuk berhubungan dengan istri',	' التسمية على كل حال وعند الوقاع'),
(4,	103,	'Bacaan do\'a memasuki kamar kecil (WC)',	' ما يقول عند الخلاء'),
(4,	104,	'Menyiapkan air di tempat buang hajat.',	' وضع الماء عند الخلاء'),
(4,	105,	'Tidak menghadap qiblat ketika buang air besar atau kecil kecuali di dalam bangunan atau di balik dinding',	' لا تستقبل القبلة بغائط أو بول إلا عند البناء جدار'),
(4,	106,	'Orang yang buang hajat besar di atas dua batu',	' من تبرز على لبنتين'),
(4,	107,	'Keluarnya wanita ke tempat buang hajat',	' خروج النساء إلى البراز'),
(4,	108,	'Buang hajat besar di rumah',	' التبرز في البيوت'),
(4,	109,	'Istinja\' (cebok) dengan air',	' الاستنجاء بالماء'),
(4,	110,	'Membawakan air untuk orang yang bersuci',	' من حمل معه الماء لطهوره'),
(4,	111,	'Membawa tongkat beserta air untuk beristinja\'',	' حمل العنزة مع الماء في الاستنجاء'),
(4,	112,	'Larangan beristinja\' menggunakan tangan kanan',	' النهي عن الاستنجاء باليمين'),
(4,	113,	'Tidak memegang kemaluan dengan tangan kanan ketika kencing',	' لا يمسك ذكره بيمينه إذا بال'),
(4,	114,	'Beristinja\' menggunakan batu',	' الاستنجاء بالحجارة'),
(4,	115,	'Larangan beristinja\' menggunakan kotoran binatang',	' لا يستنجى بروث'),
(4,	116,	'Berwudlu\' (membasuh anggota wudlu\') satu kali satu kali',	' الوضوء مرة مرة'),
(4,	117,	'Berwudlu\' (membasuh anggota wudlu\') dua kali dua kali',	' الوضوء مرتين مرتين'),
(4,	118,	'Berwudlu\' (membasuh anggota wudlu\') tiga kali tiga kali',	' الوضوء ثلاثا ثلاثا'),
(4,	119,	'al-Istintsar (mengeluarkan air yang dimasukkan kedalam hidung) dalam berwudlu\'',	' الاستنثار في الوضوء'),
(4,	120,	'Bersuci menggunakan batu dengan jumlah ganjil',	' الاستجمار وترا'),
(4,	121,	'Membasuk kedua kaki dan bukan mengusap kedua telapak kaki',	' غسل الرجلين ولا يمسح على القدمين'),
(4,	122,	'al-Madlmadlah (berkumur-kumur) dalam berwudlu\'',	' المضمضة في الوضوء'),
(4,	123,	'Membasuh tumit',	' غسل الأعقاب'),
(4,	124,	'Membasuh kaki yang menggunakan sandal bukan mengusap (sandal) nya',	' غسل الرجلين في النعلين ولا يمسح على النعلين'),
(4,	125,	'Mendahulukan yang kanan dalam berwudlu\'',	' التيمن في الوضوء والغسل'),
(4,	126,	'Berwudlu\' ketika datang waktu shalat ',	' التماس الوضوء إذا حانت الصلاة'),
(4,	127,	'Berwudlu\' dengan air yang digunakan untuk membasuh rambut',	' الماء الذي يغسل به شعر الإنسان وكان عطاء لا يرى به'),
(4,	128,	'Mereka yang berpendapat bahwa wudlu\' tidak batal selain dari apa yang keluar dari dua jalan, melalui qubul (kemaluan) atau dubur',	' من لم ير الوضوء إلا من المخرجين من القبل والدبر'),
(4,	129,	'Seserang mewudlu\'kan temannya',	' الرجل يوضئ صاحبه'),
(4,	130,	'Membaca al-Qur\'an setelah berhadats atau yang lainnya',	' قراءة القرآن بعد الحدث وغيره'),
(4,	131,	'Orang yang tidur tidak perlu berwudlu\' lagi kecuali tidur yang berat (lama) ',	' من لم يتوضأ إلا من الغشي المثقل'),
(4,	132,	'Mengusap seluruh kepala',	' مسح الرأس كله'),
(4,	133,	'Mengusap kedua kaki hingga kedua mata kaki',	' غسل الرجلين إلى الكعبين'),
(4,	134,	'Menggunakan sisa air wudlu\' orang lain',	' استعمال فضل وضوء الناس'),
(4,	135,	'Berkumur dan memasukkan air ke hidung dengan air satu cidukan',	' من مضمض واستنشق من غرفة واحدة'),
(4,	136,	'Mengusap kepala satu kali saja',	' مسح الرأس مرة'),
(4,	137,	'Seorang suami yang berwudlu\' bersama istrinya dan sisa air wudlu\' wanita',	' وضوء الرجل مع امرأته وفضل وضوء المرأة'),
(4,	138,	'Nabi Shallallahu \'alaihi wa salam menuangkan sisa air wudlu\'nya kepada orang yang pingsan',	' صب النبي صلى الله عليه وسلم وضوءه على المغمى عليه'),
(4,	139,	'Mandi dan wudlu\' menggunakan air dalam bejana yang terbuat dari gelas, kayu atau batu. ',	' الغسل والوضوء في المخضب والقدح والخشب والحجارة'),
(4,	140,	'Wudlu\' dengan air dalam bejana kecil',	' الوضوء من التور'),
(4,	141,	'Wudlu\' dengan air sebanyak satu mud',	' الوضوء بالمد'),
(4,	142,	'Mengusap khuff (sepatu yang menutupi mata kaki)',	' المسح على الخفين'),
(4,	143,	'Sesorang memasukkan kakinya ke dalam khuff dalam keadaan suci',	' إذا أدخل رجليه وهما طاهرتان'),
(4,	144,	'Tidak perlu berwudlu\' lagi seseorang yang memakan daging domba atau tepung sawiq',	' من لم يتوضأ من لحم الشاة والسويق'),
(4,	145,	'Orang yang cukup berkumur setelah makan sawiq dan tidak perlu berwudlu\'',	' من مضمض من السويق ولم يتوضأ'),
(4,	146,	'Apakah perlu berkumur-kumur setelah meminum susu?',	' هل يمضمض من اللبن'),
(4,	147,	'Wudlu\' karena ngantuk (saat shalat)',	' الوضوء من النوم ومن لم ير من النعسة والنعستين أو'),
(4,	148,	'Berwudlu\' bukan karena berhadats',	' الوضوء من غير حدث'),
(4,	149,	'Termasuk dosa besar bila kencing namun tidak menjaga kesucian dari percikannya.',	' من الكبائر أن لا يستتر من بوله'),
(4,	150,	'Membersihkan kencing',	' ما جاء في غسل البول'),
(4,	151,	'Nabi Shallallahu \'alaihi wa salam dan para shahabat membiarkan seorang Badui yang kencing di dalam masjid.',	' ترك النبي صلى الله عليه وسلم والناس الأعرابي حتى'),
(4,	152,	'Menyiramkan air ke atas (sisa) air kencing di dalam masjid',	' صب الماء على البول في المسجد'),
(4,	153,	'Kencing bayi',	' بول الصبيان'),
(4,	154,	'Kencing sambil berdiri atau duduk',	' البول قائما وقاعدا'),
(4,	155,	'Kencing di samping teman atau berlindung di balik dinding',	' البول عند صاحبه والتستر بالحائط'),
(4,	156,	'Kencing di tempat pembuangan sampah umum',	' البول عند سباطة قوم'),
(4,	157,	'Mencuci darah',	' غسل الدم'),
(4,	158,	'Mencuci air mani dan mengeriknya dan mencuci yang terkena sesuatu dari wanita',	' غسل المني وفركه وغسل ما يصيب من المرأة'),
(4,	159,	'Jika mandi janabah atau sejenisnya sedangkan bekasnya tidak hilang ',	' إذا غسل الجنابة أو غيرها فلم يذهب أثره'),
(4,	160,	'Kencing unta, binatang ternak dan kambing serta kandangnya.',	' أبوال الإبل والدواب والغنم ومرابضها'),
(4,	161,	'Najis yang jatuh ke dalam minyak samin atau air',	' ما يقع من النجاسات في السمن والماء'),
(4,	162,	'Kencing pada air yang tergenang',	' البول في الماء الدائم'),
(4,	163,	'Apabila diletakkan kotoran ke atas punggung orang yang sedang shalat maka shalatnya tidak batal',	' إذا ألقي على ظهر المصلي قذر أو جيفة لم تفسد عليه'),
(4,	164,	'Ludah, ingus dan yang sejenisnya bila mengenai pakaian',	' البزاق والمخاط ونحوه في الثوب'),
(4,	165,	'Larangan berwudlu\' menggunakan air perasan anggur atau sesuatu yang dapat memabukkan',	' لا يجوز الوضوء بالنبيذ ولا المسكر'),
(4,	166,	'Seorang wanita mencuci darah yang ada pada wajah ayahnya',	' غسل المرأة أباها الدم عن وجهه'),
(4,	167,	'Siwak',	' السواك'),
(4,	169,	'Keutamaan orang yang tidur dalam keadaan punya wudlu\'',	' فضل من بات على الوضوء'),
(5,	170,	'Berwudlu\' sebelum mandi',	' الوضوء قبل الغسل'),
(5,	171,	'Seorang suami mandi bersama istrinya',	' غسل الرجل مع امرأته'),
(5,	172,	'Mandi dengan air sebanyak satu sha\' atau seukuran dengan itu',	' الغسل بالصاع ونحوه'),
(5,	173,	'Orang yang mandi menyiram kepalanya tiga kali',	' من أفاض على رأسه ثلاثا'),
(5,	174,	'Mandi satu kali',	' الغسل مرة واحدة'),
(5,	175,	'Orang yang ketika mandi memulainya dengan hilab atau wewangian ',	' من بدأ بالحلاب أو الطيب عند الغسل'),
(5,	176,	'Berkumur dan memasukkan air ke hidung ketika mandi',	' المضمضة والاستنشاق في الجنابة'),
(5,	177,	'Menggosokkan tangan ke tanah agar lebih bersih',	' مسح اليد بالتراب لتكون أنقى'),
(5,	178,	'Bolehkan seseorang yang junub memasukkan tangannya ke dalam air sebelum mencucinya ',	' هل يدخل الجنب يده في الإناء قبل أن يغسلها إذا لم'),
(5,	179,	'Memisahkan mandi dan wudlu\'',	' تفريق الغسل والوضوء'),
(5,	180,	'Menyiramkan air ke tangan kiri dengan tangan kanan ketika mandi junub',	' من أفرغ بيمينه على شماله في الغسل'),
(5,	181,	'Bersetubuh dengan istri  lalu mengulanginya lagi, atau menggilir di istri-istri dengan sekali mandi ',	' إذا جامع ثم عاد ومن دار على نسائه في غسل واحد'),
(5,	182,	'Mencuci madzi dan berwudlu\' disebabkan keluarnya madzi',	' غسل المذي والوضوء منه'),
(5,	183,	'Siapa yang memakai wewangian lalu mandi namun aromanya masih tersisa',	' من تطيب ثم اغتسل وبقي أثر الطيب'),
(5,	184,	'Menyela-nyela rambut ketika seseorang mandi junub hingga bila merasa sudah membasahi kulit kepalanya maka dia menyiramnya',	' تخليل الشعر حتى إذا ظن أنه قد أروى بشرته أفاض عليه'),
(5,	185,	'Siapa yang berwudlu\' dalam keadaan junub lalu mandi dengan membasuh seluruh badannya tidak perlu mengulang mandi',	' من توضأ في الجنابة ثم غسل سائر جسده ولم يعد غسل'),
(5,	186,	'Jika seseorang berada di masjid dan teringat bahwa dia sedang junub maka dia keluar (untuk mandi) sebagaimana mestinya dan bukan bertayamum',	' إذا ذكر في المسجد أنه جنب يخرج كما هو ولا يتيمم'),
(5,	187,	'Mengeringkan air dari badan setelah mandi junub dengan tangan',	' نفض اليدين من الغسل عن الجنابة'),
(5,	188,	'Memulai mandi junub dengan menggosok kepala bagian kanan',	' من بدأ بشق رأسه الأيمن في الغسل'),
(5,	189,	'Mandi dalam keadaan telanjang di tempat yang sepi dan bila dapat menggunakan tutup lebih baik',	' من اغتسل عريانا وحده في الخلوة ومن تستر فالتستر'),
(5,	190,	'Berlindung (menggunakan tutup) ketika mandi di tengah orang',	' التستر في الغسل عند الناس'),
(5,	191,	'Jika seorang wanita bermimpi (basah)',	' إذا احتلمت المرأة'),
(5,	192,	'Keringat orang yang junub dan bahwa seorang muslim (badannya) tidaklah najis',	' عرق الجنب وأن المسلم لا ينجس'),
(5,	193,	'Orang yang junub boleh keluar rumah dan mendatangi pasar atau lainnya',	' الجنب يخرج ويمشي في السوق وغيره'),
(5,	194,	'Keberadaan orang yang junub di rumah jika sudah berwudlu namun belum mandi',	' كينونة الجنب في البيت إذا توضأ قبل أن يغتسل'),
(5,	195,	'Orang junub yang tidur',	' نوم الجنب'),
(5,	196,	'Orang yang junub berwudlu\' lalu tidur',	' الجنب يتوضأ ثم ينام'),
(5,	197,	'Apabila dua kemaluan bertemu',	' إذا التقى الختانان'),
(5,	198,	'Mencuci bagian badan yang terkena sesuatu yang keluar dari kemaluan wanita',	' غسل ما يصيب من فرج المرأة'),
(6,	199,	'Bagimana permulaan junub',	' كيف كان بدء الحيض'),
(6,	200,	'Wanita yang sedang haidl boleh mencuci kepala suaminya dan menyisir rambutnya ',	' غسل الحائض رأس زوجها وترجيله'),
(6,	201,	'Seorang suami membaca al-Qur\'an di pangkuan istrinya yang sedang haidl',	' قراءة الرجل في حجر امرأته وهي حائض'),
(6,	202,	'Mereka yang menamakan nifas sebagai haidl dan sebaliknya',	' من سمى النفاس حيضا والحيض نفاسا'),
(6,	203,	'Bercumbu dengan istri yang sedang haidl',	' مباشرة الحائض'),
(6,	204,	'Wanita yang sedang haidl meninggalkan shaum (puasa) ',	' ترك الحائض الصوم'),
(6,	205,	'Wanita yang sedang haidl melaksanakan seluruh manasik hajji kecuali thawaf di Baitullah',	' تقضي الحائض المناسك كلها إلا الطواف بالبيت'),
(6,	206,	'al-Istihadlah',	' الاستحاضة'),
(6,	207,	'Mencuci darah haidl',	' غسل دم المحيض'),
(6,	208,	'I\'tikaf bagi wanita yang sedang mustahadlah',	' اعتكاف المستحاضة'),
(6,	209,	'Apakah seorang wanita boleh shalat menggunakan pakaian yang pernah dipakainya ketika haidl?',	' هل تصلي المرأة في ثوب حاضت فيه'),
(6,	210,	'Memakai wewangian bagi wanita ketika mandi dari haidl',	' الطيب للمرأة عند غسلها من المحيض'),
(6,	211,	'Wanita menggosok badannya ketika mandi dari haidl dan cara dia mandi dengan menggunakan kapas untuk membersihkan sisa darah',	' دلك المرأة نفسها إذا تطهرت من المحيض وكيف تغتسل'),
(6,	212,	'Mandi dari haidl',	' غسل المحيض'),
(6,	213,	'Seorang wanita menyisir rambutnya ketika mandi dari haidl',	' امتشاط المرأة عند غسلها من المحيض'),
(6,	214,	'Mengurai rambut bagi wanita yang mandi dari haidl',	' نقض المرأة شعرها عند غسل المحيض'),
(6,	215,	'Firman Allah Ta\'ala: \"Yang kejadiannya sempurna dan yang tidak sempurna\"',	' قول الله عز وجل مخلقة وغير مخلقة'),
(6,	216,	'Bagaimana wanita yang sedang haidl melakukan ihram (dan bertalbiyah) hajji dan \'umrah',	' كيف تهل الحائض بالحج والعمرة'),
(6,	217,	'Awal dan akhir masa haidl',	' إقبال المحيض وإدباره'),
(6,	218,	'Wanita haidl tidak mengqadla shalat yang ditinggalkannya ketika sedang haidl',	' لا تقضي الحائض الصلاة'),
(6,	219,	'Tidur bersama istri yang sedang haidl dan berselimut bersamanya dengan pakaian yang dipakainya',	' النوم مع الحائض وهي في ثيابها'),
(6,	220,	'Menggunakan pakian khusus untuk haidl selain pakaian saat suci',	' من اتخذ ثياب الحيض سوى ثياب الطهر'),
(6,	221,	'Wanita haid menghadiri shalat dua Hari Raya dan mendegarkan khutbah dan do\'a bagi Kaum Muslimin namun mereka dijauhkan dari tempat shalat',	' شهود الحائض العيدين ودعوة المسلمين ويعتزلن المصلى'),
(6,	222,	'Jika seorang wanita mengalami tiga kali masa haidl dalam sebulan dan apa yang harus dilakukannya dalam masa-masa haidl',	' إذا حاضت في شهر ثلاث حيض وما يصدق النساء في الحيض'),
(6,	223,	'Cairan kuning dan coklat yang keluar diluar masa-masa haidl',	' الصفرة والكدرة في غير أيام الحيض'),
(6,	224,	'Darah (penyakit) istihadlah',	' عرق الاستحاضة'),
(6,	225,	'Seorang wanita mengalami haidl setelah melaksanakan thawaf ifadalah',	' المرأة تحيض بعد الإفاضة'),
(6,	226,	'Jika wanita yang sedang mengalami haidl melihat tanda-tanda suci',	' إذا رأت المستحاضة الطهر'),
(6,	227,	'Menshalatkan wanita yang meninggal dunia dalam keadaan nifas serta sunnah-sunnahnya',	' الصلاة على النفساء وسنتها'),
(7,	228,	'Firman Allah \"Lalu kalian tidakmendapatkan air, maka bertayamumlah…\"',	' وقول الله تعالى فلم تجدوا ماء فتيمموا صعيدا طيبا فامسحوا'),
(7,	229,	'Bagaimana bila tidak mendapatkan air dan debu?',	' إذا لم يجد ماء ولا ترابا'),
(7,	230,	'Tayamum bagi muqim yang tidak mendapatkan air',	' التيمم في الحضر إذا لم يجد الماء وخاف فوت الصلاة'),
(7,	231,	'Apakah orang yang bertayamum meniup debu ditelapak tangannya? ',	' المتيمم هل ينفخ فيهما'),
(7,	232,	'Bertayamum dengan mengusap wajah dan kedua telapak tangan',	' التيمم للوجه والكفين'),
(7,	233,	'Tanah yang bersih cukup sebagai sarana bersuci bagi Kaum Muslimin sebagai pengganti air',	' الصعيد الطيب وضوء المسلم يكفيه من الماء'),
(7,	234,	'Jika seorang yang junub khawatir atas dirinya menjadi sakit, mati atau kehausan bila mandi, maka dia boleh tayamum',	' إذا خاف الجنب على نفسه المرض أو الموت أو خاف العطش'),
(7,	235,	'Tayamum dengan sekali tepukan (menempelkan kedua telapak tangan pada debu)',	' التيمم ضربة'),
(8,	236,	'Bagaimana shalat diwajibkam pada malam Isra\'',	' كيف فرضت الصلاة في الإسراء'),
(8,	237,	'Wajibnya melaksanakan shalat dengan menggunakan pakaian',	' وجوب الصلاة في الثياب'),
(8,	238,	'Mengikatkan pakaian di tengkuk ketika shalat',	' عقد الإزار على القفا في الصلاة'),
(8,	239,	'Shalat dengan menggunakan sehelai pakaian',	' الصلاة في الثوب الواحد ملتحفا به'),
(8,	240,	'Jika shalat menggunakan sehelai pakaian hendaklah mengikatkannya ke pundaknya',	' إذا صلى في الثوب الواحد فليجعل على عاتقيه'),
(8,	241,	'Apabila pakaian yang dikenakan untuk shalat sempit',	' إذا كان الثوب ضيقا'),
(8,	242,	'Shalat dengan menggunakan jubah buatan negeri Syam',	' الصلاة في الجبة الشامية'),
(8,	243,	'Tidak disukainya badan terbuka (selain penutup aurat)  ketika shalat dan juga di luar shalat',	' كراهية التعري في الصلاة وغيرها'),
(8,	244,	'Shalat dengan menggunakan kemeja, celana panang, celana dalam, dan selendang',	' الصلاة في القميص والسراويل والتبان والقباء'),
(8,	245,	'Sesuatu yang digunakan untuk menutup aurat',	' ما يستر من العورة'),
(8,	246,	'Shalat tanpa meggunakan rida\' (selendang yang lebar)',	' الصلاة بغير رداء'),
(8,	247,	'Masalah berkenaan paha (apakah termasuk aurat?)',	' ما يذكر في الفخذ'),
(8,	248,	'Dalam berapa lembar pakaian seharusnya wanita melaksanakan shalat?',	' في كم تصلي المرأة في الثياب'),
(8,	249,	'Jika seseorang shalat dengan pakaian yang ada gambanya lalu dia memperhatikan gambar tersebut',	' إذا صلى في ثوب له أعلام ونظر إلى علمها'),
(8,	250,	'Jika seseorang shalat dengan pakaian yang ada salibnya atau gambar, apakah dapat merusak shalatnya?.Apa yang terlarang berkaitan masalah ini?',	' إن صلى في ثوب مصلب أو تصاوير هل تفسد صلاته وما ينهى'),
(8,	251,	'Shalat mengenakan baju luar yang terbuat dari sutera lalu menanggalkannya',	' من صلى في فروج حرير ثم نزعه'),
(8,	252,	'Shalat mengenakan baju berwarna merah',	' الصلاة في الثوب الأحمر'),
(8,	253,	'Shalat di atap, di atas mimpar dan atau di atas kayu',	' الصلاة في السطوح والمنبر والخشب'),
(8,	254,	'Jika orang yang shalat ketika sujud pakaiannya menyentuh istrinya',	' إذا أصاب ثوب المصلي امرأته إذا سجد'),
(8,	255,	'Shalat di atas tikar',	' الصلاة على الحصير'),
(8,	256,	'Shalat di atas al-khumrah (alas kecil khusus untuk tempat sujud)',	' الصلاة على الخمرة'),
(8,	257,	'Shalat di atas alas tidur (kasur)',	' الصلاة على الفراش'),
(8,	258,	'Sujud di atas kain dalam cuaca sangat panas',	' السجود على الثوب في شدة الحر'),
(8,	259,	'Shalat dengan memakai sandal',	' الصلاة في النعال'),
(8,	260,	'Shalat dengan memakai khuff (sepatu yang menutupi maka kaki)',	' الصلاة في الخفاف'),
(8,	261,	'Shalat bila tidak menyempurnakan sujud',	' إذا لم يتم السجود'),
(8,	262,	'Menampakkan ketiak dan merenggangkan lengan saat sujud',	' يبدي ضبعيه ويجافي في السجود'),
(8,	263,	'Keutamaan menghadap qiblat dengan menghadapkan jari jemari kedua kaki',	' فضل استقبال القبلة يستقبل بأطراف رجليه'),
(8,	264,	'Arah qiblat bagi penduduk Madinah, Syam dan penduduk Timur ( dari Ka\'bah)',	' قبلة أهل المدينة وأهل الشأم والمشرق'),
(8,	265,	'Firman Allah \"Dan jadikanlah sebagian dari maqam Ibrahim sebagai tempat shalat\"',	' قول الله تعالى واتخذوا من مقام إبراهيم مصلى'),
(8,	266,	'Menghadap qiblat bagaimanapun keadaannya ',	' التوجه نحو القبلة حيث كان'),
(8,	267,	'Masalah qiblat dan mereka yang memandang tidak perlu mengulang shalat bagi siapa yang telah shalat namun keliru arah qiblatnya',	' ما جاء في القبلة ومن لم ير الإعادة على من سها فصلى'),
(8,	268,	'Mengerik dahak yang ada di masjid dengan tangan',	' حك البزاق باليد من المسجد'),
(8,	269,	'Mengerik dahak yang ada di masjid dengan kerikil',	' حك المخاط بالحصى من المسجد'),
(8,	270,	'Tidak boleh meludah ke arah kanan ketika shalat',	' لا يبصق عن يمينه في الصلاة'),
(8,	271,	'Hendaklah membuang dahak ke sebeleh kiri atau di bawah kaki kiri keika shalat',	' ليبزق عن يساره أو تحت قدمه اليسرى'),
(8,	272,	'Kafarat (tebusan) akibat membuang dahak di dalam masjid',	' كفارة البزاق في المسجد'),
(8,	273,	'Menutupi (mengubur) dahak di masjid',	' دفن النخامة في المسجد'),
(8,	274,	'Jika terpaksa meludah hendaklah meludahnya dengan mengunakan ujung pakaiannya',	' إذا بدره البزاق فليأخذ بطرف ثوبه'),
(8,	275,	'Nasehat imam kepada para ma\'mum tentang menyempurnakan shalat dan mengingatkan qiblat',	' عظة الإمام الناس في إتمام الصلاة وذكر القبلة'),
(8,	276,	'Bolehkan menamakan masjid dengan Masjid Suku anu?',	' هل يقال مسجد بني فلان'),
(8,	278,	'Orang yang mengundang makan di masjid dan orang yang memenuhi undangan tersebut',	' من دعا لطعام في المسجد ومن أجاب فيه'),
(8,	279,	'Memutuskan perkara-perkara dan li\'an (sumpah dan saling melaknat) antara suami dan istri di masjid',	' القضاء واللعان في المسجد بين الرجال والنساء'),
(8,	280,	'Jika seseorang memasuki suatu rumah apakah ia boleh shalat dimana saja dia mau atau dimana diperintahkan tanpa menyelidiki terlebih dahulu?  ',	' إذا دخل بيتا يصلي حيث شاء أو حيث أمر ولا يتجسس'),
(8,	281,	'Masjid-masjid yang ada di rumah-rumah',	' المساجد في البيوت'),
(8,	282,	'Mendahului kaki kanan ketika memasuki masjid dan lainnya',	' التيمن في دخول المسجد وغيره'),
(8,	283,	'Bolehkan menmbongkar kuburan orang musyrik jahiliyyah lalu membangun masjid di atasnya?',	' هل تنبش قبور مشركي الجاهلية ويتخذ مكانها مساجد'),
(8,	284,	'Shalat di kandang kambing',	' الصلاة في مرابض الغنم'),
(8,	285,	'Shalat di kandang unta',	' الصلاة في مواضع الإبل'),
(8,	286,	'Orang yang melakukan shalat di hadapan tungku atau api atau sesuatu yang biasa disembah orang sedangkan dia melaksanakan shalat karena Allah Ta\'ala',	' من صلى وقدامه تنور أو نار أو شيء مما يعبد فأراد'),
(8,	287,	'Dibencinya shalat di kuburan',	' كراهية الصلاة في المقابر'),
(8,	288,	'Shalat di tempat reruntuhan atau tempat yang pernah terkena siksa',	' الصلاة في مواضع الخسف والعذاب'),
(8,	289,	'Shalat di dalam gereja (atau tempat ibadah orangYahudi dan Nashrani)',	' الصلاة في البيعة'),
(8,	290,	'Sabda Nabi Shallallahu \'alaihi wa salam: \"Dan bumi telah dijadikan untukku sebagai tempat sujud dan tempat bersuci\"',	' قول النبي صلى الله عليه وسلم جعلت لي الأرض مسجدا'),
(8,	291,	'Tidurnya seorang wanita di dalam masjid',	' نوم المرأة في المسجد'),
(8,	292,	'Tidurnya seorang laki-laki di dalam masjid',	' نوم الرجال في المسجد'),
(8,	293,	'Shalat sekembalinya dari bepergian',	' الصلاة إذا قدم من سفر'),
(8,	294,	'Jika seorang dari kalian memasuki masjid hendaklah shalat dua rakaat sebelum dia duduk',	' إذا دخل أحدكم المسجد فليركع ركعتين قبل أن يجلس'),
