(9,	362,	'Waktu shalat \'Isya\' jika manusia sudah berkumpul atau belum datang.',	' وقت العشاء إذا اجتمع الناس أو تأخروا'),
(9,	363,	'Keutamaan shalay \'Isya\'',	' فضل العشاء'),
(9,	364,	'Tidak disukainya tidur sebelum shalat \'Isya\'',	' ما يكره من النوم قبل العشاء'),
(9,	365,	'Tidur sebelum shalat \'Isya\' bagi orang yakin tidak akan ketiduran',	' النوم قبل العشاء لمن غلب'),
(9,	366,	'Waktu shalat \'Isya sampai pertengahan malam',	' وقت العشاء إلى نصف الليل'),
(9,	367,	'Keutamaan shalat Fajar (Shubuh)',	' فضل صلاة الفجر'),
(9,	368,	'Waktu shalat Shubuh',	' وقت الفجر'),
(9,	369,	'Orang yang mendapatkan satu raka\'at shalat Shubuh pada waktunya',	' من أدرك من الفجر ركعة'),
(9,	370,	'Orang yang mendapatkan satu raka\'at dari shalat.',	' من أدرك من الصلاة ركعة'),
