(9,	381,	'Membahas masalah fiqih dan hal-hal yang baik setelah \'Isya\'',	' السمر في الفقه والخير بعد العشاء'),
(9,	382,	'Mengobrol bersama keluarga dan tamu',	' السمر مع الضيف والأهل'),
(10,	383,	'Permulaan (diperintahkannya) adzan',	' بدء الأذان'),
(10,	384,	'Adzan dua kali dua kali',	' الأذان مثنى مثنى'),
