(10,	390,	'Do\'a setelah panggilan adzan',	' الدعاء عند النداء'),
(10,	391,	'Berlomba untuk mengumandangkan adzan',	' الاستهام في الأذان'),
(10,	392,	'Berbicara ketika adzan',	' الكلام في الأذان'),
(10,	393,	'Adzannya orang yang buta jika diberitahu masuknya waktu shalat',	' أذان الأعمى إذا كان له من يخبره'),
(10,	394,	'Adzan setelah Shubuh',	' الأذان بعد الفجر'),
(10,	395,	'Adzan sebelum Shubuh',	' الأذان قبل الفجر'),
