(25,	1447,	'Dosa yang menahan ibnu sabil dari mendapatkan air',	' إثم من منع ابن السبيل من الماء'),
(25,	1448,	'Menutup suangi-sungai',	' سكر الأنهار'),
(25,	1449,	'Yang atas sebelum yang bawah',	' شرب الأعلى قبل الأسفل'),
(25,	1450,	'Mengairi bagian atas hingga sebatas mata kaki',	' شرب الأعلى إلى الكعبين'),
(25,	1451,	'Memberi air minum ',	' فضل سقي الماء'),
