(25,	1455,	'Menjual kayu bakar dan rumput',	' بيع الحطب والكلإ'),
(25,	1456,	'Pembagian tanah',	' القطائع'),
(25,	1458,	'Memerah unta setelah memberinya (hak) minum',	' حلب الإبل على الماء'),
(25,	1459,	'Seseorang yang tempat lewat, atau tempat minum pada kebun, atau kurma',	' الرجل يكون له ممر أو شرب في حائط أو في نخل'),
