(26,	1462,	'Membayar hutang',	' أداء الدين'),
(26,	1463,	'Menghutangkan unta',	' استقراض الإبل'),
(26,	1464,	'Baik dalam meminta pembayaran',	' حسن التقاضي'),
(26,	1465,	'Apakah diberi dengan yang lebih tua umurnya?',	' هل يعطى أكبر من سنه'),
(26,	1466,	'Baik dalam pembayaran',	' حسن القضاء'),
