(27,	1484,	'Mengaku mendapatkan wasiat dari orang yang sudah meninggal',	' دعوى الوصي للميت'),
(27,	1485,	'Mengambil jaminan dari orang yang dikhawatirkan perbuatan buruknya',	' التوثق ممن تخشى معرته'),
(27,	1486,	'Mengikat dan menahan di tanah haram',	' الربط والحبس في الحرم'),
(27,	1487,	'Penjelasan tentang mulazamah',	' في الملازمة'),
(27,	1488,	'Menagih pembayaran hutang',	' التقاضي'),
(28,	1489,	'Jika pemilik barang menyebutkan ciri-ciri barang yang hilang, maka si penemu harus memberikannya',	' إذا أخبره رب اللقطة بالعلامة دفع إليه'),
