(29,	1500,	'Qishash perbutaan zhalim',	' قصاص المظالم'),
(29,	1501,	'Firman Allah \"Ingatlah, kutukan Allah ditimpakan atas orang-orang yang zhalim\"',	' قول الله تعالى ألا لعنة الله على الظالمين'),
