(30,	1537,	'Pembagian kambing',	' قسمة الغنم'),
(30,	1538,	'Makan kurma dua biji-dua biji sekaligus di antara orang-orang yang iut berseriat, kecuali dengan seizin mereka',	' القران في التمر بين الشركاء حتى يستأذن أصحابه'),
