(32,	1574,	'Jika budaknya datang dengan membawa makanannya',	' إذا أتاه خادمه بطعامه'),
(32,	1575,	'Budak itu pemimpin atas harta tuannya',	' العبد راع في مال سيده'),
(32,	1576,	'Jika memukul budak hendaklah menjauhi wajah',	' إذا ضرب العبد فليجتنب الوجه'),
(32,	1578,	'Persyaratan yang dibolehkan dalam Mukatab',	' ما يجوز من شروط المكاتب'),
(32,	1579,	'Budak mukatab minta bantuan dan meminta-minta kepada orang lain',	' استعانة المكاتب وسؤاله الناس'),
(32,	1580,	'Menjual budak mukatab jika rela',	' بيع المكاتب إذا رضي'),
(32,	1581,	'Jika budak mukatab berkata \'Beli dan memerdekakanlah aku,',	' إذا قال المكاتب اشترني وأعتقني فاشتراه لذلك'),
(33,	1582,	'Bab',	' باب'),
(33,	1583,	'Menghibahkan barang yang sedikit',	' القليل من الهبة'),
(33,	1584,	'Orang yang minta hibah dari kawannya',	' من استوهب من أصحابه شيئا'),
(33,	1585,	'Meminta minum',	' من استسقى'),
(33,	1586,	'Menerima hadiah dari hasil buruan',	' قبول هدية الصيد'),
(33,	1587,	'Menerima hadiah ',	' قبول الهدية'),
(33,	1588,	'Orang yang memberikan hadiah kepada sahabatnya',	' من أهدى إلى صاحبه وتحرى بعض نسائه دون بعض'),
(33,	1589,	'Hadiah yang tidak ditolak',	' ما لا يرد من الهدية'),
(33,	1590,	'Pendapat yang mengatakan \"Boleh menghibahkan barang yang tidak ada di tempat\"',	' من رأى الهبة الغائبة جائزة'),
(33,	1591,	'Imbalan dalam hibah',	' المكافأة في الهبة'),
(33,	1592,	'Hibah untuk anak',	' الهبة للولد'),
(33,	1593,	'Saksi dalam hibah',	' الإشهاد في الهبة'),
(33,	1594,	'Hibah suami untuk isteri dan isteri untuk suami',	' هبة الرجل لامرأته والمرأة لزوجها'),
(33,	1595,	'Menghibahkan seorang budal wanita kepada selain suaminya',	' هبة المرأة لغير زوجها وعتقها إذا كان لها زوج فهو'),
(33,	1596,	'Kepada siapa hadiah harus dahulu diberikan?',	' بمن يبدأ بالهدية'),
(33,	1597,	'Tidak menerima hadiah karena ada sebab',	' من لم يقبل الهدية لعلة'),
(33,	1598,	'Jika menerima hibah atau menjanjikannya, kemudian ia meninggal sebelum hibah tersebut diberikan',	' إذا وهب هبة أو وعد عدة ثم مات قبل أن تصل إليه'),
(33,	1599,	'Bagaimana serah terima budak dan barang?',	' كيف يقبض العبد والمتاع'),
(33,	1600,	'Jika memberikan hibah kemudian diterima oleh orang lain, namun ia tidak mengatakan \'Aku telah menerimanya\'',	' إذا وهب هبة فقبضها الآخر ولم يقل قبلت'),
(33,	1601,	'Jika menghibahkan hutang kepada orang lain',	' إذا وهب دينا على رجل'),
(33,	1602,	'Hibah satu orang untuk orang banyak',	' هبة الواحد للجماعة'),
(33,	1603,	'Hibah yang telah diambil dan yang belum, hibah yang telah dibagi dan yang belum',	' الهبة المقبوضة وغير المقبوضة والمقسومة وغير المقسومة'),
(33,	1604,	'Jika suatu jamaah memberi hibah untuk suatu kaum',	' إذا وهب جماعة لقوم'),
(33,	1605,	'Barangsiapa diberi hibang dan di sekelilingnya ada banyak orang, maka ia lebih berhak',	' من أهدي له هدية وعنده جلساؤه فهو أحق'),
(33,	1607,	'Hadiah sesuatu yang dilarang untuk dipakai',	' هدية ما يكره لبسها'),
(33,	1608,	'Menerima hadiah dari orang musyrik',	' قبول الهدية من المشركين'),
(33,	1609,	'Hadiah untuk orang musyrik',	' الهدية للمشركين'),
(33,	1610,	'Seseorang tidak boleh mengambil kembali sesuatu yang dihibahkannya',	' لا يحل لأحد أن يرجع في هبته وصدقته'),
(33,	1611,	'Penjelasan tentang umra dan ruqba',	' ما قيل في العمرى والرقبى'),
(33,	1612,	'Meminjam kuda dan hewan tunggangan dan selainnya dari manusia',	' من استعار من الناس الفرس والدابة وغيرها'),
(33,	1613,	'Meminjam untuk pengantin saat nikah',	' الاستعارة للعروس عند البناء'),
(33,	1614,	'Keutamaan menihah',	' فضل المنيحة'),
(33,	1615,	'Jika seseorang berkata \'Aku berikan budak ini untuk membantumu sebagaimana yang lazim diketahui oleh manusia\',',	' إذا قال أخدمتك هذه الجارية على ما يتعارف الناس فهو'),
(33,	1616,	'Jika memberi tumpangan seseorang di atas kuda maka itu seperti umra dan sedekah',	' إذا حمل رجلا على فرس فهو كالعمرى والصدقة'),
(34,	1618,	'Jika seseorang menilai adil kepada seseorang, lalu ia berkata,  \'Kami tidak mengetahui kecuali kebaikan\',',	' إذا عدل رجل أحدا فقال لا نعلم إلا خيرا أو قال ما علمت'),
(34,	1619,	'Persaksian orang yang biasa menipu',	' شهادة المختبي'),
(34,	1620,	'Jika seorang saksi memberi persaksian, atau memberi persaksian dengan sesuatu',	' إذا شهد شاهد أو شهود بشيء وقال آخرون ما علمنا ذلك'),
(34,	1621,	'Persaksian orang yang adil',	' الشهداء العدول'),
(34,	1622,	'Penilaian adil, berapa jumlah yang dibutuhan?',	' تعديل كم يجوز'),
(34,	1623,	'Persaksian terhadap nasab, persusuan penuh dan kematian yang telah berlalu lama',	' الشهادة على الأنساب والرضاع المستفيض والموت القديم'),
(34,	1624,	'Persaksian orang yang menuduh, pencuri dan pezina',	' شهادة القاذف والسارق والزاني'),
(34,	1625,	'Tidak boleh bersaksi dengan persaksian palsu',	' لا يشهد على شهادة جور إذا أشهد'),
(34,	1626,	'Penjelasan tentang persaksian palsu',	' ما قيل في شهادة الزور'),
(34,	1627,	'Persaksian orang buta, perintahnya, pernikahannya, menikahkannya, ',	' شهادة الأعمى وأمره ونكاحه وإنكاحه ومبايعته وقبوله'),
(34,	1628,	'Persaksian seorang wanita',	' شهادة النساء'),
(34,	1629,	'Persaksian budak laki-laki dan perempuan',	' شهادة الإماء والعبيد'),
(34,	1630,	'Persaksian wanita yang menyusui',	' شهادة المرضعة'),
(34,	1631,	'Kaum wanita, sebagian dengan sebagian yang lain memberi penilaian adil',	' تعديل النساء بعضهن بعضا'),
(34,	1632,	'Jika seseorang menilai  bersih kepada orang lain maka itu sudah cukup',	' إذا زكى رجل رجلا كفاه'),
(34,	1633,	'Berbelit-belit dalam memberikan pujian dan hendaklah mengatakan apa yang dia ketahui',	' ما يكره من الإطناب في المدح وليقل ما يعلم'),
(34,	1634,	'Balighnya anak kecil dan nilai persaksiannya',	' بلوغ الصبيان وشهادتهم'),
(34,	1635,	'Pertanyaan hakim kepada pihak penuduh, \'Apakah kamu mempunyai bukti?\'',	' سؤال الحاكم المدعي هل لك بينة قبل اليمين'),
(34,	1636,	'Sumpah bagi orang yang tertuduh',	' اليمين على المدعى عليه في الأموال والحدود'),
(34,	1637,	'Jika seseorang mengajukan dakwahan atau tuduhan, ',	' إذا ادعى أو قذف فله أن يلتمس البينة وينطلق لطلب'),
(34,	1638,	'Sumpah setelah asar',	' اليمين بعد العصر'),
(34,	1639,	'Pikah yang tertuduh memberikan sumpahnya sekiranya sumpah itu wajib bagi dirinya,',	' يحلف المدعى عليه حيثما وجبت عليه اليمين ولا يصرف'),
(34,	1640,	'Jika suatu kaum saling berebut untuk saling bersumpah',	' إذا تسارع قوم في اليمين'),
(34,	1641,	'Firman Allah \"Sesungguhnya orang-orang yang menukar janji (nya dengan) Allah…\"',	' قول الله تعالى إن الذين يشترون بعهد الله وأيمانهم'),
(34,	1642,	'Bagimana seseorang diminta untuk bersumpah',	' كيف يستحلف'),
(34,	1643,	'Seseorang yang memberikan bukti setelah jatuhnya sumpah',	' من أقام البينة بعد اليمين'),
(34,	1644,	'Orang yang memerintahkan untuk menepati janji',	' من أمر بإنجاز الوعد'),
(34,	1645,	'Orang musyrik tidak diminta untuk bersaksi',	' لا يسأل أهل الشرك عن الشهادة وغيرها'),
(34,	1646,	'Mengundi dalam hal-hal yang membingungkan',	' القرعة في المشكلات'),
(35,	1647,	'Penjelasan tentang mendamaikan antara manusia',	' ما جاء في الإصلاح بين الناس إذا تفاسدوا وقول الله تعالى'),
(35,	1648,	'Bukan disebut  dusta orang yang mendamaikan antara manusia',	' ليس الكاذب الذي يصلح بين الناس'),
(35,	1649,	'Ucapan imam untuk sahabatnya \'Perilah dengan bersama kami untuk mendamaikan\"',	' قول الإمام لأصحابه اذهبوا بنا نصلح'),
(35,	1650,	'firman Allah \"Bagi keduanya mengadakan perdamaian dengan perdamaian yang sebenar-benarnya\"',	' قول الله تعالى أن يصالحا بينهما صلحا والصلح خير'),
(35,	1651,	'Mengadakan perdamaian dengan perjanjian yang curang',	' إذا اصطلحوا على صلح جور فالصلح مردود'),
(35,	1652,	'Bagaimana jika tertulis \'Ini adalah perdamaian antara fulan bin fulan\'',	' كيف يكتب هذا ما صالح فلان بن فلان وفلان بن فلان وإن'),
(35,	1653,	'Damai dengan orang-orang musyrik',	' الصلح مع المشركين'),
(35,	1654,	'Perdamaian dalam diat',	' الصلح في الدية'),
(35,	1655,	'Sabda Nabi Shallallahu \'alaihi wa Sallam kepada Hasan bin Ali',	' قول النبي صلى الله عليه وسلم للحسن بن علي رضي'),
(35,	1656,	'Bolehkah imam memberikan isyarat untuk damai',	' هل يشير الإمام بالصلح'),
(35,	1657,	'Keutamaan mendamaikan dengan sesama manusia',	' فضل الإصلاح بين الناس والعدل بينهم'),
(35,	1658,	'Jika imam memberikan isyarat namun yang bersangkutan tidak mau',	' إذا أشار الإمام بالصلح فأبى حكم عليه بالحكم البين'),
(35,	1659,	'Perdamaian antara pihak pemberi hutang dengan orang yang menerima waris',	' الصلح بين الغرماء وأصحاب الميراث والمجازفة في ذلك'),
(35,	1660,	'Berdamai dengan hutang dan barang',	' الصلح بالدين والعين'),
(36,	1661,	'Syarat-syarat yang diperbolehkan dalam Islam, hukum-hukum',	' ما يجوز من الشروط في الإسلام والأحكام والمبايعة'),
(36,	1662,	'Jika menjual pohon kurma yang sudah masak',	' إذا باع نخلا قد أبرت ولم يشترط الثمرة'),
(36,	1663,	'Syarat-syarat dalam jual beli',	' الشروط في البيوع'),
(36,	1664,	'Jika penjual memberi syarat pada punggung hewan (menungganginya)',	' إذا اشترط البائع ظهر الدابة إلى مكان مسمى جاز'),
(36,	1665,	'Syarat-syarat dalam mua\'malah',	' الشروط في المعاملة'),
(36,	1666,	'Syarat-syarat dalam akad nikah',	' الشروط في المهر عند عقدة النكاح'),
(36,	1667,	'Syarat-syarat dalam muzara\'ah',	' الشروط في المزارعة'),
(36,	1668,	'Syarat-syarat yang tidak boleh dalam jual beli',	' ما لا يجوز من الشروط في النكاح'),
(36,	1669,	'Syarat yang tidak boleh dalam hudud',	' الشروط التي لا تحل في الحدود'),
(36,	1670,	'Syarat-syarat yang diperbolehkan pada budak mukatab',	' ما يجوز من شروط المكاتب إذا رضي بالبيع على أن يعتق'),
(36,	1671,	'Syarat-syarat dalam talak',	' الشروط في الطلاق'),
(36,	1672,	'Memberikan syarat kepada manusia dengan ucapan',	' الشروط مع الناس بالقول'),
(36,	1673,	'Syarat-syarat dalam wala`',	' الشروط في الولاء'),
(36,	1674,	'Jika seseorang memberi syarat dalam muzara\'ah \'Jika mau, aku bisa keluarkan kamu\'',	' إذا اشترط في المزارعة إذا شئت أخرجتك'),
(36,	1675,	'Syarat-syarat dalam jihad dan perdamaian dengan kafir harbi',	' الشروط في الجهاد والمصالحة مع أهل الحرب وكتابة الشروط'),
(36,	1677,	'Syarat-syarat yang menyimpang dari Kitabullah tidak boleh dalam Mukatab',	' المكاتب وما لا يحل من الشروط التي تخالف كتاب الله'),
(36,	1678,	'Mengajukan persyarat yang dibolehkan, pengecualian dalam ikrar',	' ما يجوز من الاشتراط والثنيا في الإقرار والشروط التي'),
(36,	1679,	'Syarat-syarat dalam wakaf ',	' الشروط في الوقف'),
(37,	1680,	'Bab: Wasiat dan sabda Nabi Shallallahu \'alaihi wa Sallam ',	'بَاب الْوَصَايَا وَقَوْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصِيَّةُ الرَّجُلِ مَكْتُوبَةٌ عِنْدَهُ وَقَوْلِ اللَّهِ تَعَالَى\n{ كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمْ الْمَوْتُ إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ فَمَنْ بَدَّلَهُ بَعْدَ مَا سَمِعَهُ فَإِنَّمَا إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ فَمَنْ خَافَ مِنْ مُوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَا إِثْمَ عَلَيْهِ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ }\n{ جَنَفًا }\nمَيْلًا مُتَجَانِفٌ مَائِلٌ'),
(37,	1681,	'Meninggalkan ahli waris dalam keadaan kaya',	' أن يترك ورثته أغنياء خير من أن يتكففوا الناس'),
(37,	1682,	'Memberi wasiat dengan sepertiga',	' الوصية بالثلث'),
(37,	1683,	'Perkataan orang yang memberi wasiat kepada orang yang menerima wasiat',	' قول الموصي لوصيه تعاهد ولدي وما يجوز للوصي من الدعوى'),
(37,	1684,	'Jika orang yang sakit memberi isyarat dengan kepalanya dengan isyarat yang jelas',	' إذا أومأ المريض برأسه إشارة بينة جازت'),
(37,	1685,	'Tidak ada wasiat untuk penerima waris',	' لا وصية لوارث'),
(37,	1686,	'Sedekah saat meninggal',	' الصدقة عند الموت'),
(37,	1687,	'Firman Allah \"Sesudah dipenuhi wasiat yang Ia buat atau (dan) sesudah dibayar hutangnya\"',	' قول الله تعالى من بعد وصية يوصي بها أو دين'),
(37,	1688,	'Takwil firman Allah \"Sesudah dipenuhi wasiat yang Ia buat…\"',	' تأويل قول الله تعالى من بعد وصية يوصي بها أو دين'),
(37,	1689,	'Jika seseorang memberi wakaf atau wasiat kepada kerabatnya',	' إذا وقف أو أوصى لأقاربه ومن الأقارب'),
(37,	1690,	'Apakah wanita dan anak  masuk ke dalam kelompok kerabat',	' هل يدخل النساء والولد في الأقارب'),
(37,	1691,	'Apakah pemberi wakaf boleh memanfaarkan (barang) wakaf',	' هل ينتفع الواقف بوقفه'),
(37,	1694,	'Seseorang yang mengatakan \"Tanahku atau kebunku sedekah untuk Allah dan pahalanya untuk ibuku\"',	' إذا قال أرضي أو بستاني صدقة لله عن أمي فهو جائز وإن'),
(37,	1695,	'Jika seseorang sedekah atau memberi wakaf dengan sebagian hartanya atau sebagian budaknya',	' إذا تصدق أو أوقف بعض ماله أو بعض رقيقه أو دوابه'),
(37,	1697,	'Firman Allah \"dan apabila sewaktu pembagian itu hadir kerabat…\"',	' قول الله تعالى وإذا حضر القسمة أولو القربى واليتامى'),
(37,	1698,	'Sesuatu yang dianjurkan untuk seseorang yang meninggal dengan tiba-tiba agar mereka bersedekah untuknya atau melaksanakan nadzarnya',	' ما يستحب لمن توفي فجاءة أن يتصدقوا عنه وقضاء النذور'),
(37,	1699,	'Persaksian dalam wakaf dan sedekah',	' الإشهاد في الوقف والصدقة'),
(37,	1700,	'Firman Allah \"Dan berikanlkah kepada anak-anak yatim yang sudah baligh harta mereka…\"',	' قول الله تعالى وآتوا اليتامى أموالهم ولا تتبدلوا الخبيث'),
(37,	1701,	'Firman Allah \"Dan ujilah anak-anak yatim itu hingga sampai mereka cukup umur untuk kawin…\"',	' قول الله تعالى وابتلوا اليتامى حتى إذا بلغوا النكاح'),
(37,	1702,	'Firman Allah \"Sesungguhnya orang-orang yang makan harta anak yatim secara zhalim…\"',	' قول الله تعالى إن الذين يأكلون أموال اليتامى ظلما'),
(37,	1704,	'Memperbantukan anak yatim dalam perjalanan ',	' استخدام اليتيم في السفر والحضر إذا كان صلاحا له ونظر'),
(37,	1705,	'Jika seseorang mewakafkan tanah namun tidak menjelaskan batas-batasnya',	' إذا وقف أرضا ولم يبين الحدود فهو جائز وكذلك الصدقة'),
(37,	1706,	'Jika satu jamaah mewakafkan tanah milik bersama ',	' إذا أوقف جماعة أرضا مشاعا فهو جائز'),
(37,	1707,	'Bagaimana menulis akad wakaf ',	' الوقف كيف يكتب'),
(37,	1708,	'Wakaf untuk orang kaya, fakir dan lemah',	' الوقف للغني والفقير والضيف'),
(37,	1709,	'Mewakafkan tanah untuk masjid',	' وقف الأرض للمسجد'),
(37,	1710,	'Mewakafkan hewan tunggangan, kuda, barang dangangan dan harta benda',	' وقف الدواب والكراع والعروض والصامت'),
(37,	1711,	'Nafkah orang yang mengurus wakaf',	' نفقة القيم للوقف'),
(37,	1713,	'Jika orang yang memberi wakaf berkata \"Kami tidak meminta harganya kecuali kepada Allah…\"',	' إذا قال الواقف لا نطلب ثمنه إلا إلى الله فهو جائز'),
(37,	1714,	'Firman Allah \"Hai orang-orang yang beriman, jika kamu menghadapi kematian…\"',	' قول الله تعالى يا أيها الذين آمنوا شهادة بينكم إذا'),
(37,	1715,	'Penerima wasiat membayarkan hutang mayit tanpa memberitahukan pihak ahli waris',	' قضاء الوصي ديون الميت بغير محضر من الورثة'),
(38,	1716,	'Keutamaan jihad',	' فضل الجهاد والسير'),
