(45,	2219,	'[Bab] Surat al Baqarah ayat 116',	' وقالوا اتخذ الله ولدا سبحانه'),
(45,	2220,	'[Bab] Surat al Baqarah ayat 125',	' واتخذوا من مقام إبراهيم مصلى'),
