(77,	3832,	'Ajakan Nabi Shallallahu ‘Alaihi Wa Sallam kepada umatnya untuk mentauhidkan Allah Ta\'ala',	' ما جاء في دعاء النبي صلى الله عليه وسلم أمته إلى'),
(77,	3833,	'Firman Allah Ta\'ala: {Katakan wahai Muhammad: serulah Allah atau serulah Ar Rahman} ',	' قول الله تبارك وتعالى قل ادعوا الله أو ادعوا الرحمن'),
(77,	3834,	'Firman Allah Ta\'ala: {Dialah (Allah) sang permberi rizqi yang memiliki segala kekuatan}',	' قول الله تعالى إن الله هو الرزاق ذو القوة المتين'),
(77,	3835,	'Firman Allah Ta\'ala: {Yang Mengetahui yang ghaib, maka Dia tidak memperlihatkan kepada seorangpun tentang yang ghaib itu}.',	' قول الله تعالى عالم الغيب فلا يظهر على غيبه أحدا'),
(77,	3836,	'Firman Allah Ta\'ala: { Yang Maha Sejahtera, Yang Mengaruniakan Keamanan}',	' قول الله تعالى السلام المؤمن'),
(77,	3837,	'Firman Allah Ta\'ala: {Raja manusia}',	' قول الله تعالى ملك الناس فيه ابن عمر عن النبي صلى'),
(77,	3838,	'Firman Allah Ta\'ala: {Dialah (Allah) yang maha kuasa dan maha bijaksana}',	' قول الله تعالى وهو العزيز الحكيم'),
(77,	3839,	'Firman Allah Ta\'ala: {Dialah Allah yang telah menciptakan langit dan bumi dengan sebenar-benarnya}',	' قول الله تعالى وهو الذي خلق السموات والأرض بالحق'),
(77,	3840,	'Firman Allah Ta\'ala: {Sesungguhnya Allah maha mendengar dan melihat}',	' قول الله تعالى وكان الله سميعا بصيرا'),
(77,	3841,	'Firman Allah Ta\'ala: {Dialah (Allah) yang berkuasa atas segala sesuatu}',	' قول الله تعالى قل هو القادر'),
(77,	3842,	'Yang membolak-balikkan hati',	' مقلب القلوب'),
(77,	3843,	'Sesungguhnya Allah memiliki sembilan puluh sembilan nama',	' إن لله مائة اسم إلا واحدا'),
(77,	3844,	'Memohon dan berlindung dengan perantara nama-nama Allah',	' السؤال بأسماء الله تعالى والاستعاذة بها'),
(77,	3845,	'Penjelasan mengenai dzat, sifat dan nama-nama Allah',	' ما يذكر في الذات والنعوت وأسامي الله'),
(77,	3846,	'Firman Allah Ta\'ala: {Dan Allah memperingatkan kamu terhadap diri -Nya}. ',	' قول الله تعالى ويحذركم الله نفسه'),
(77,	3847,	'Firman Allah Ta\'ala: {Segala sesuatu akan binasa kecuali wajah-Nya}',	' قول الله تعالى كل شيء هالك إلا وجهه'),
(77,	3848,	'Firman Allah Ta\'ala {dan supaya kamu diasuh di bawah pengawasan-Ku}',	' قول الله تعالى ولتصنع على عيني'),
(77,	3849,	'Firman Allah Ta\'ala {Dialah Allah Yang Menciptakan, Yang Mengadakan, Yang Membentuk Rupa}',	' قول الله هو الله الخالق البارئ المصور'),
(77,	3850,	'Firman Allah Ta\'ala: {yang  telah Ku-ciptakan  dengan  kedua  tangan-Ku}',	' قول الله تعالى لما خلقت بيدي'),
(77,	3851,	'Sabda Nabi Shallallahu ‘Alaihi Wa Sallam: Tidak seorang pun yang lebih cemburu selain Allah',	' قول النبي صلى الله عليه وسلم لا شخص أغير من الله'),
(77,	3852,	'Katakanlah: \"Siapakah yang lebih kuat persaksiannya?\" Katakanlah: \"Allah\"',	' قل أي شيء أكبر شهادة قل الله'),
(77,	3853,	'dan adalah singgasana-Nya  di atas air (Al An\'am: 7), Dia adalah Tuhan yang memiliki \'Arsy yang agung (At Taubah: 129)',	' وكان عرشه على الماء وهو رب العرش العظيم'),
(77,	3854,	'Firman Allah Ta\'ala: {Malaikat-malaikat dan Jibril naik  kepada Tuhan} ',	' قول الله تعالى تعرج الملائكة والروح إليه'),
(77,	3855,	'Firman Allah Ta\'ala: {Wajah-wajah  pada hari itu berseri-seri, Kepada Tuhannyalah mereka melihat}',	' قول الله تعالى وجوه يومئذ ناضرة إلى ربها ناظرة'),
(77,	3856,	'Firman Allah Ta\'ala: {Sesungguhnya rahmat Allah amat dekat kepada orang-orang yang berbuat baik}',	' ما جاء في قول الله تعالى إن رحمة الله قريب من المحسنين'),
(77,	3857,	'Firman Allah Ta\'ala: {Sesungguhnya Allah menahan langit dan bumi supaya jangan lenyap}',	' قول الله تعالى إن الله يمسك السموات والأرض أن تزولا'),
(77,	3858,	'Penciptaan langit dan bumi serta ciptaan Allah yang lainnya',	' ما جاء في تخليق السموات والأرض وغيرها من الخلائق'),
(77,	3859,	'Firman Allah Ta\'ala: {Dan sesungguhnya telah tetap janji Kami kepada hamba-hamba Kami yang menjadi rasul}',	' قوله تعالى ولقد سبقت كلمتنا لعبادنا المرسلين'),
(77,	3860,	'Firman Allah Ta\'ala: {Sesungguhnya perkataan Kami terhadap sesuatu apabila Kami menghendakinya, Kami hanya mengatakan kepadanya: \"kun \", maka jadilah ia}.',	' قول الله تعالى إنما قولنا لشيء إذا أردناه أن نقول'),
(77,	3861,	'Firman Allah Ta\'ala: {Katakanlah: Sekiranya lautan menjadi tinta untuk  kalimat-kalimat Tuhanku, sungguh habislah lautan itu sebelum habis  kalimat-kalimat Tuhanku, meskipun Kami datangkan tambahan sebanyak itu}',	' قول الله تعالى قل لو كان البحر مدادا لكلمات ربي لنفد'),
(77,	3862,	'Kehendak dan keinginan',	' في المشيئة والإرادة'),
(77,	3863,	'Firman Allah Ta\'ala: {Dan tiadalah berguna syafa\'at di sisi Allah melainkan bagi orang yang telah diizinkan-Nya memperoleh syafa\'at itu}',	' قول الله تعالى ولا تنفع الشفاعة عنده إلا لمن أذن'),
(77,	3864,	'Dialog Allah bersama Jibril dan panggilan Allah kepada para Malaikat',	' كلام الرب مع جبريل ونداء الله الملائكة'),
(77,	3865,	'Firman Allah Ta\'ala: {Allah menurunkannya dengan ilmu-Nya; dan malaikat-malaikat pun menjadi saksi} ',	' قول الله تعالى أنزله بعلمه والملائكة يشهدون'),
(77,	3866,	'Firman Allah Ta\'ala: {mereka  hendak  merubah  janji   Allah}.',	' قول الله تعالى يريدون أن يبدلوا كلام الله'),
(77,	3867,	'Dialog Allah bersama para nabi dan selain mereka pada hari kiamat',	' كلام الرب عز وجل يوم القيامة مع الأنبياء وغيرهم'),
(77,	3868,	'Firman Allah Ta\'ala: {Allah berbicara dengan Musa secara langsung}',	' قوله وكلم الله موسى تكليما'),
(77,	3869,	'Dialog Allah bersama penghuni surga',	' كلام الرب مع أهل الجنة'),
(77,	3871,	'Firman Allah Ta\'ala: {Janganlah kalian menjadikan tandingan-tandingan bagi Allah}',	' قول الله تعالى فلا تجعلوا لله أندادا'),
(77,	3872,	'Firman Allah Ta\'ala: {Kamu sekali-sekali tidak dapat bersembunyi dari kesaksian pendengaran, penglihatan dan kulitmu kepadamu} ',	' قول الله تعالى وما كنتم تستترون أن يشهد عليكم سمعكم'),
(77,	3873,	'Firman Allah Ta\'ala: {Setiap waktu Dia dalam kesibukan} ',	' قول الله تعالى كل يوم هو في شأن'),
(77,	3874,	'Firman Allah Ta\'ala: {Janganlah kamu gerakkan lidahmu untuk  Al Qur\'an karena hendak bercepat-cepat.}',	' قول الله تعالى لا تحرك به لسانك وفعل النبي صلى الله'),
(77,	3875,	'Firman Allah Ta\'ala: {Dan rahasiakanlah perkataanmu atau lahirkanlah; sesungguhnya Dia Maha Mengetahui segala isi hati}',	' قول الله تعالى وأسروا قولكم أو اجهروا به إنه عليم'),
(77,	3876,	'Sabda Rasulullah  Shallallahu ‘Alaihi Wa Sallam: \"Seorang hamba yang diberikan kepadanya Al Qur\'an\"',	' قول النبي صلى الله عليه وسلم رجل آتاه الله القرآن'),
(77,	3877,	'Firman Allah Ta\'ala: {Wahai Rasul, sampaikanlah apa yang telah diturunkan kepadamu dari Rabbmu',	' قول الله تعالى يا أيها الرسول بلغ ما أنزل إليك من'),
(77,	3878,	'Firman Allah Ta\'ala: {maka bawalah Taurat itu, lalu bacalah dia jika kamu orang-orang yang benar}',	' قول الله تعالى قل فأتوا بالتوراة فاتلوها'),
(77,	3879,	'Nabi Shallallahu ‘Alaihi Wa Sallam menamakan shalat sebagai sebuah amalan',	' وسمى النبي صلى الله عليه وسلم الصلاة عملا'),
(77,	3880,	'Firman Allah Ta\'ala: {Sesungguhnya manusia diciptakan bersifat keluh kesah lagi kikir}',	' قول الله تعالى إن الإنسان خلق هلوعا إذا مسه الشر'),
(77,	3881,	'Apa yang disampaikan Nabi Shallallahu ‘Alaihi Wa Sallam berdasarkan riwayat dari Rabbnya',	' ذكر النبي صلى الله عليه وسلم وروايته عن ربه'),
(77,	3882,	'penafsiran yang di perbolehkan dari kitab-kitab Allah seperti Taurat dan yang lainnya dengan bahasa Arab.',	' ما يجوز من تفسير التوراة وغيرها من كتب الله بالعربية'),
(77,	3883,	'Sabda Nabi Shallallahu \'alaihi wa sallam: \"orang yang mahir (membaca) Al Qur\'an bersama para malaikat yang mulia lagi berbakti.\" dan \"Hiasilah Al Qur`an dengan suara-suara kalian.\"',	' قول النبي صلى الله عليه وسلم الماهر بالقرآن مع'),
(77,	3884,	'Firman Allah Ta\'ala: \"Maka bacalah apa yang mudah (bagimu) dari Al Qur\'an.\"',	' قول الله تعالى فاقرءوا ما تيسر من القرآن'),
(77,	3885,	'Firman Allah Ta\'ala: \"dan sungguh kami telah memudahkan Al Qur`an untuk pelajaran, maka adakah orang yang mengambil pelajaran?\" dan Sabda Nabi Shallallahu \'alaihi wa sallam: \"semuanya dimudahkan berdasarkan penciptaannya.\"',	' قول الله تعالى ولقد يسرنا القرآن للذكر فهل من مدكر'),
(77,	3886,	'Firman Allah Ta\'ala: \"Bahkan yang mereka dustakan itu adalah Al Qur`an yang mulia, yang (tersimpan) di lauhul Mahfudz\"',	' قول الله تعالى بل هو قرآن مجيد في لوح محفوظ'),
(77,	3887,	'Firman Allah Ta\'ala: \"Dan Allah yang mencipatakan kalian dan apa yang kalian kerjakan\" \"Sesungguhnya Kami menciptakan segala sesuatu menurut ukuran\" dan dikatakan kepada orang-orang yang menggambar; \'hidupkanlah apa yang kalian ciptakan.\'',	' قول الله تعالى والله خلقكم وما تعملون إنا كل شيء'),
(77,	3888,	'Bacaan orang yang fajir dan munafiq, serta suara dan tilawah mereka tidak melampaui kerongkongan mereka.',	' قراءة الفاجر والمنافق وأصواتهم وتلاوتهم لا تجاوز'),
(77,	3889,	'Firman Allah Ta\'ala: \"dan kami letakkan neraca timbangan yang adil pada hari kiamat,\" dan bahwasanya amalan anak adam dan ucapan mereka akan di timbang.',	' قول الله تعالى ونضع الموازين القسط ليوم القيامة وأن');
